        return {}
    a,b=names[:2]
    p=[r["close"] for r in history[a]]
    q=[r["close"] for r in history[b]]
    n=min(len(p),len(q))
    if n<41:
        return {}
    spreads=[math.log(x/y) for x,y in zip(p[-41:],q[-41:])]
    past=spreads[:-1]
    mean=sum(past)/40.0
    sd=(sum((x-mean)**2 for x in past)/39.0)**0.5
    if sd<1e-8:
        return {}
    z=(spreads[-1]-mean)/sd
    if z>1.5:
        return {a:-0.5,b:0.5}
    if z<-1.5:
        return {a:0.5,b:-0.5}
    return {}

