def signals(history):
    names=sorted(history)
    if len(names)<3 or any(len(history[t])<42 for t in names):
        return {}
    r={}
    for t in names:
        c=[row["close"] for row in history[t]]
        r[t]=[c[i]/c[i-1]-1.0 for i in range(len(c)-41,len(c))]
    market=[sum(r[t][k] for t in names)/len(names) for k in range(41)]
    mx=sum(market[:-1])/40.0
    mv=sum((x-mx)**2 for x in market[:-1])
    if mv<1e-12:
        return {}
    scores=[]
    for t in names:
        ys=r[t][:-1]
        my=sum(ys)/40.0
        beta=sum((x-mx)*(y-my) for x,y in zip(market[:-1],ys))/mv
        resid=r[t][-1]-(my+beta*(market[-1]-mx))
        scores.append((resid,t))
    scores.sort()
    if scores[0][1]==scores[-1][1]:
        return {}
    return {scores[0][1]:0.5,scores[-1][1]:-0.5}

