import math
def signals(history):
    names=sorted(history)
    if len(names)<2:
        return {}
    a,b=names[:2]
    x=[r["close"] for r in history[a]]
    y=[r["close"] for r in history[b]]
    if min(len(x),len(y))<61:
        return {}
    mom_a=x[-1]/x[-61]-1
    mom_b=y[-1]/y[-61]-1
    if (mom_a>0)!=(mom_b>0):
        return {}
    spread=[math.log(i/j) for i,j in zip(x[-61:],y[-61:])]
    hist=spread[:-1]
    mu=sum(hist)/60.0
    sd=(sum((v-mu)**2 for v in hist)/59.0)**0.5
    if sd<1e-8:
        return {}
    z=(spread[-1]-mu)/sd
    return {a:-0.5,b:0.5} if z>1.8 else ({a:0.5,b:-0.5} if z<-1.8 else {})

